/*
 * Engine interpreter tests.  Guest code = pre-assembled ARM/Thumb blobs
 * (blobs.h, generated by gen_blobs.py and committed).  Expected results
 * are computed by hand from the documented semantics of each blob.
 *
 * Also covers: shim dispatch (host-backed imports), and on x86_64 /
 * aarch64 the host-callable trampoline.  If TRIANGO_TEST_SO points at a
 * cross-built arm32 .so, an ELF load + trampoline integration test runs.
 */
#include "../engine_internal.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "blobs.h"

static int g_pass, g_fail;

#define CHECK(name, expr)                                                    \
	do {                                                                 \
		if (expr) {                                                  \
			g_pass++;                                            \
		} else {                                                     \
			g_fail++;                                            \
			printf("FAIL %s (%s:%d): %s\n", name, __FILE__,      \
			       __LINE__, #expr);                             \
		}                                                            \
	} while (0)

static t32_space g_mem;
static t32_cpu g_cpu;

static uint32_t load_blob(const void *code, size_t len, int thumb)
{
	uint32_t base;
	void *p = t32_map(&g_mem, (uint32_t)((len + 7u) & ~7u), &base);

	if (!p) {
		printf("FATAL: blob map failed\n");
		exit(1);
	}
	memcpy(p, code, len);
	return thumb ? (base | 1u) : base;
}

static uint32_t call1(uint32_t fn, uint32_t a0, uint32_t a1, uint32_t a2)
{
	uint32_t args[3] = { a0, a1, a2 };
	uint32_t r = t32_call(&g_cpu, &g_mem, fn, args, 3);

	if (g_cpu.trap) {
		printf("  trap=%d pc=%08x insn=%08x\n", g_cpu.trap,
		       g_cpu.trap_pc, g_cpu.trap_insn);
		g_fail++;
	}
	return r;
}

/* ---- host shim used by the shim-dispatch test ---- */

static uint64_t host_mix(uint64_t a0, uint64_t a1, uint64_t a2, uint64_t a3)
{
	(void)a3;
	return (uint32_t)a0 + ((uint32_t)a1 << 8) + ((uint32_t)a2 << 16);
}

static void emit_movw_movt(uint8_t *dst, uint32_t rd, uint32_t v)
{
	/* movw rd, #lo16 ; movt rd, #hi16 (verified encodings) */
	uint32_t lo = v & 0xFFFFu, hi = v >> 16;
	uint32_t h1, h2;

	/* imm4 = lo[15:12], i = lo[11], imm3 = lo[10:8], imm8 = lo[7:0] */
	h1 = 0xF240u | (((lo >> 11) & 1u) << 10) | ((lo >> 12) & 0xFu);
	h2 = (((lo >> 8) & 7u) << 12) | (rd << 8) | (lo & 0xFFu);
	memcpy(dst, &h1, 2);
	memcpy(dst + 2, &h2, 2);
	h1 = 0xF2C0u | (((hi >> 11) & 1u) << 10) | ((hi >> 12) & 0xFu);
	h2 = (((hi >> 8) & 7u) << 12) | (rd << 8) | (hi & 0xFFu);
	memcpy(dst + 4, &h1, 2);
	memcpy(dst + 6, &h2, 2);
}

int main(void)
{
	uint32_t fn, r, arr, shim, code, cb;
	uint32_t args[4];
	uint8_t scratch[64];

	t32_space_init(&g_mem);
	t32_shim_install_builtins(&g_mem);

	/* ---- ARM mode ---- */
	fn = load_blob(blob_arm_add, sizeof(blob_arm_add), 0);
	CHECK("arm_add", call1(fn, 0, 7, 35) == 42); /* r1 + r2 */

	fn = load_blob(blob_arm_flags, sizeof(blob_arm_flags), 0);
	CHECK("arm_flags", call1(fn, 0, 0, 0) == 0x80000001u);

	fn = load_blob(blob_arm_sum_loop, sizeof(blob_arm_sum_loop), 0);
	CHECK("arm_sum_loop", call1(fn, 0, 0, 10) == 55);

	{
		uint32_t base;
		uint32_t *p = t32_map(&g_mem, 16, &base);
		int i;

		for (i = 0; i < 4; i++)
			p[i] = (uint32_t)(i + 1);
		fn = load_blob(blob_arm_sum_array, sizeof(blob_arm_sum_array), 0);
		CHECK("arm_sum_array", call1(fn, base, 4, 0) == 10);
	}

	fn = load_blob(blob_arm_mla, sizeof(blob_arm_mla), 0);
	{
		/* mla r0, r1, r2, r3 -> r1*r2 + r3 */
		uint32_t a4[4] = { 0, 3, 5, 7 };
		uint32_t rv = t32_call(&g_cpu, &g_mem, fn, a4, 4);

		CHECK("arm_mla", !g_cpu.trap && rv == 22);
	}

	fn = load_blob(blob_arm_stack, sizeof(blob_arm_stack), 0);
	CHECK("arm_stack", call1(fn, 1, 2, 3) == 6);

	/* ---- Thumb-16 ---- */
	fn = load_blob(blob_t_adds, sizeof(blob_t_adds), 1);
	CHECK("t_adds", call1(fn, 20, 22, 0) == 42);

	fn = load_blob(blob_t_sum_loop, sizeof(blob_t_sum_loop), 1);
	CHECK("t_sum_loop", call1(fn, 0, 0, 10) == 55);

	fn = load_blob(blob_t_push_pop, sizeof(blob_t_push_pop), 1);
	CHECK("t_push_pop", call1(fn, 10, 32, 0) == 42);

	/* ---- Thumb-2 ---- */
	fn = load_blob(blob_t2_movw_movt, sizeof(blob_t2_movw_movt), 1);
	CHECK("t2_movw_movt", call1(fn, 0, 0, 0) == 0x56781234u);

	{
		uint32_t base;
		uint32_t *p = t32_map(&g_mem, 16, &base);

		*p = 0;
		fn = load_blob(blob_t2_mem, sizeof(blob_t2_mem), 1);
		CHECK("t2_mem", call1(fn, base, 0xCAFEBABEu, 0) == 0xCAFEBABEu);
		CHECK("t2_mem-stored", *p == 0xCAFEBABEu);

		fn = load_blob(blob_t2_mem_reg, sizeof(blob_t2_mem_reg), 1);
		CHECK("t2_mem_reg",
		      call1(fn, base, 0x11223344u, 4) == 0x11223344u);
		CHECK("t2_mem_reg-stored", p[1] == 0x11223344u);
	}

	fn = load_blob(blob_t2_bl, sizeof(blob_t2_bl), 1);
	CHECK("t2_bl", call1(fn, 0, 0, 0) == 14);

	fn = load_blob(blob_t2_muldiv, sizeof(blob_t2_muldiv), 1);
	CHECK("t2_muldiv", call1(fn, 6, 7, 5) == 8);

	fn = load_blob(blob_t2_bitfield, sizeof(blob_t2_bitfield), 1);
	CHECK("t2_bitfield", call1(fn, 0xF0, 0xAB, 0) == 0xAB);

	{
		uint32_t base;
		uint32_t *p = t32_map(&g_mem, 16, &base);

		memset(p, 0, 16);
		fn = load_blob(blob_t2_memw, sizeof(blob_t2_memw), 1);
		CHECK("t2_memw", call1(fn, base, 0x1234, 0) == 0x1268);
	}

	fn = load_blob(blob_t2_shifts, sizeof(blob_t2_shifts), 1);
	CHECK("t2_shifts", call1(fn, 1, 4, 3) == 19);

	fn = load_blob(blob_t2_adrw, sizeof(blob_t2_adrw), 1);
	CHECK("t2_adrw", call1(fn, 0, 0, 0) == 0x100);

	fn = load_blob(blob_t2_clz_rev, sizeof(blob_t2_clz_rev), 1);
	CHECK("t2_clz_rev",
	      call1(fn, 0, 0x00100000u, 0x11223344u) == 0x4433221Cu);

	/* ---- shim dispatch from guest code ---- */
	shim = t32_shim_install(&g_mem, "host_mix", host_mix);
	CHECK("shim-install", shim != 0);
	{
		uint8_t *p;
		uint32_t base;

		/* movw r3, #lo(shim); movt r3, #hi(shim); blx r3; bx lr */
		p = t32_map(&g_mem, 16, &base);
		emit_movw_movt(p, 3, shim);
		p[8] = 0x98; p[9] = 0x47; /* blx r3 */
		p[10] = 0x70; p[11] = 0x47; /* bx lr */
		r = t32_call(&g_cpu, &g_mem, base | 1u, (uint32_t[]){ 3, 4, 5 }, 3);
		CHECK("shim-call", !g_cpu.trap &&
		      r == (3u + (4u << 8) + (5u << 16)));
	}

	/* ---- trampoline (host-callable stub) ---- */
#if defined(__x86_64__) || defined(__aarch64__)
	fn = load_blob(blob_arm_add, sizeof(blob_arm_add), 0);
	{
		void *stub = t32_trampoline_build(&g_cpu, &g_mem, fn);

		CHECK("trampoline-build", stub != NULL);
		if (stub) {
			uint32_t (*host_fn)(uint32_t, uint32_t, uint32_t,
					    uint32_t) = stub;

			CHECK("trampoline-call",
			      host_fn(0, 7, 35, 0) == 42); /* r1 + r2 */
			CHECK("trampoline-call2", host_fn(0, 1, 2, 0) == 3);
		}
	}
#endif

	/* ---- direct shim table sanity ---- */
	CHECK("shim-find", t32_shim_find(&g_mem, "memcpy") != 0);
	CHECK("shim-at", t32_shim_at(&g_mem,
				     t32_shim_find(&g_mem, "memcpy")) != NULL);
	CHECK("shim-at-miss", t32_shim_at(&g_mem, 0x00001234u) == NULL);

	/* ---- memory fault diagnostics ---- */
	fn = load_blob(blob_t2_mem, sizeof(blob_t2_mem), 1);
	args[0] = 0xF0000000u; /* unmapped */
	args[1] = 1;
	args[2] = 0;
	t32_call(&g_cpu, &g_mem, fn, args, 3);
	CHECK("mem-fault", g_cpu.trap == T32_TRAP_MEM);

	/* ---- optional ELF integration (cross-built .so) ---- */
	{
		const char *so = getenv("TRIANGO_TEST_SO");

		if (so && so[0]) {
			t32_module mod;
			char err[256];

			if (t32_elf_load(&g_mem, so, &mod, NULL, 0, err,
					 sizeof(err)) != 0) {
				printf("FAIL elf-load: %s\n", err);
				g_fail++;
			} else {
				uint32_t sym = t32_elf_symbol(&mod, "guest_add");
				void *stub;

				CHECK("elf-symbol", sym != 0);
				stub = t32_trampoline_build(&g_cpu, &g_mem,
							    sym);
				CHECK("elf-stub", stub != NULL);
				if (stub) {
					uint32_t (*hf)(uint32_t, uint32_t,
						       uint32_t,
						       uint32_t) = stub;

					CHECK("elf-call", hf(20, 22, 0, 0) == 42);
				}
			}
		}
	}

	(void)scratch;
	(void)cb;
	printf("engine-tests: %d passed, %d failed\n", g_pass, g_fail);
	return g_fail ? 1 : 0;
}
